import { JunaiEventBus } from '../background/events';
import { checkPermission } from '../permissions/approvalPolicy';
import { TaskGraph, type CoordinatorTaskSpec, type TaskResult } from './taskGraph';
import { executeWorker } from './workerRunner';

export interface CoordinationRequest {
    title: string;
    goal: string;
    workers: CoordinatorTaskSpec[];
}

export type FindingSeverity = 'info' | 'warning' | 'error';
export type FindingConfidence = 'low' | 'medium' | 'high';

export interface CoordinatorFinding {
    id: string;
    title: string;
    severity: FindingSeverity;
    evidence: string;
    file?: string;
    confidence: FindingConfidence;
    recommendedAction?: string;
}

export interface CoordinatorSynthesisResult {
    format: 'markdown-v1';
    content: string;
    findings: CoordinatorFinding[];
}

export interface CoordinationResult {
    title: string;
    goal: string;
    workerResults: TaskResult[];
    synthesis: CoordinatorSynthesisResult;
    synthesizedOutput: string;
    totalDurationMs: number;
    summary: ReturnType<TaskGraph['getSummary']>;
}

const SEVERITY_SCORE: Record<FindingSeverity, number> = {
    error: 3,
    warning: 2,
    info: 1,
};

const CONFIDENCE_SCORE: Record<FindingConfidence, number> = {
    high: 3,
    medium: 2,
    low: 1,
};

function normalizeFindingKey(value: string): string {
    return value.trim().toLowerCase().replace(/\s+/g, ' ');
}

function extractFileReference(line: string): string | undefined {
    const fileMatch = line.match(/`([^`]+)`/);
    return fileMatch?.[1];
}

function createFinding(input: Omit<CoordinatorFinding, 'id'>): CoordinatorFinding {
    const idBase = [input.severity, input.file ?? '', input.title, input.evidence].join(':');
    return {
        id: normalizeFindingKey(idBase),
        ...input,
    };
}

export function synthesizeFindings(results: TaskResult[]): CoordinatorFinding[] {
    const findingsByKey = new Map<string, CoordinatorFinding>();

    for (const result of results) {
        if (result.status === 'failure') {
            const finding = createFinding({
                title: `Worker failed: ${result.label}`,
                severity: 'error',
                evidence: result.error ?? 'Unknown worker error',
                confidence: 'high',
                recommendedAction: 'Review worker scope and retry with narrower inputs.',
            });
            findingsByKey.set(finding.id, finding);
            continue;
        }

        const lines = result.output.split('\n').map((line) => line.trim()).filter(Boolean);
        for (const line of lines) {
            if (line.includes('❌') || /not found/i.test(line)) {
                const file = extractFileReference(line);
                const finding = createFinding({
                    title: 'Missing path or verification failure',
                    severity: 'warning',
                    evidence: line,
                    file,
                    confidence: 'high',
                    recommendedAction: 'Confirm path assumptions and adjust worker scope.',
                });
                findingsByKey.set(finding.id, finding);
                continue;
            }

            const todoMatch = line.match(/TODOs\/FIXMEs:\s*(\d+)/i);
            if (todoMatch && Number(todoMatch[1]) > 0) {
                const finding = createFinding({
                    title: 'Outstanding TODO/FIXME markers',
                    severity: 'warning',
                    evidence: line,
                    confidence: 'medium',
                    recommendedAction: 'Review TODO/FIXME markers before finalizing synthesis.',
                });
                findingsByKey.set(finding.id, finding);
                continue;
            }

            if (/access denied/i.test(line)) {
                const finding = createFinding({
                    title: 'Scope path access denied',
                    severity: 'warning',
                    evidence: line,
                    confidence: 'medium',
                    recommendedAction: 'Adjust scope paths to readable directories.',
                });
                findingsByKey.set(finding.id, finding);
            }
        }
    }

    return [...findingsByKey.values()]
        .sort((a, b) => {
            const severityDelta = SEVERITY_SCORE[b.severity] - SEVERITY_SCORE[a.severity];
            if (severityDelta !== 0) {
                return severityDelta;
            }

            const confidenceDelta = CONFIDENCE_SCORE[b.confidence] - CONFIDENCE_SCORE[a.confidence];
            if (confidenceDelta !== 0) {
                return confidenceDelta;
            }

            return a.title.localeCompare(b.title);
        })
        .slice(0, 12);
}

export function synthesizeResults(goal: string, results: TaskResult[]): string {
    const sections: string[] = [];

    sections.push('## Coordination Summary\n');
    sections.push(`**Goal:** ${goal}\n`);

    const succeeded = results.filter((result) => result.status === 'success');
    const failed = results.filter((result) => result.status === 'failure');

    sections.push(`**Workers:** ${results.length} total — ${succeeded.length} succeeded, ${failed.length} failed\n`);

    if (succeeded.length > 0) {
        sections.push('---\n');
        for (const result of succeeded) {
            sections.push(result.output);
            sections.push(`\n*Worker \`${result.workerId}\` completed in ${result.durationMs}ms*\n`);
        }
    }

    if (failed.length > 0) {
        sections.push('---\n\n### ⚠ Failed Workers\n');
        for (const result of failed) {
            sections.push(`- **${result.label}** (\`${result.workerId}\`): ${result.error ?? 'Unknown error'}`);
        }
    }

    return sections.join('\n');
}

export async function coordinate(
    request: CoordinationRequest,
    workspaceRoot: string,
): Promise<CoordinationResult> {
    const eventBus = JunaiEventBus.getInstance();
    const graph = new TaskGraph();
    const startTime = Date.now();

    for (const worker of request.workers) {
        graph.addWorker(worker);
    }

    const settledResults = await Promise.allSettled(
        graph.getPendingWorkers().map(async (worker): Promise<TaskResult> => {
            const action = worker.type === 'explore' ? 'search_workspace' : 'read_file';
            const permission = checkPermission(action, 'autopilot');

            if (!permission.allowed) {
                const blockedResult: TaskResult = {
                    workerId: worker.id,
                    workerType: worker.type,
                    label: worker.label,
                    status: 'failure',
                    output: '',
                    durationMs: 0,
                    error: permission.reason,
                };
                graph.markCompleted(worker.id, blockedResult);
                eventBus.emit({
                    type: 'task-blocked',
                    timestamp: new Date().toISOString(),
                    source: 'coordinator',
                    severity: 'warning',
                    title: `Coordinator worker blocked: ${worker.label}`,
                    detail: permission.reason,
                    stage: 'coordinate',
                    agent: worker.label,
                    reason: permission.reason,
                });
                return blockedResult;
            }

            graph.markRunning(worker.id);
            const result = await executeWorker(worker, workspaceRoot);
            graph.markCompleted(worker.id, result);

            if (result.status === 'success') {
                eventBus.emit({
                    type: 'task-completed',
                    timestamp: new Date().toISOString(),
                    source: 'coordinator',
                    severity: 'success',
                    title: `Coordinator worker complete: ${worker.label}`,
                    detail: `Worker ${worker.id} completed successfully`,
                    stage: 'coordinate',
                    agent: worker.label,
                    summary: `Worker ${worker.id} completed successfully`,
                });
            } else {
                eventBus.emit({
                    type: 'task-blocked',
                    timestamp: new Date().toISOString(),
                    source: 'coordinator',
                    severity: 'warning',
                    title: `Coordinator worker failed: ${worker.label}`,
                    detail: result.error ?? 'Worker failed',
                    stage: 'coordinate',
                    agent: worker.label,
                    reason: result.error ?? 'Worker failed',
                });
            }

            return result;
        }),
    );

    const workerResults: TaskResult[] = settledResults.map((settled, index) => {
        if (settled.status === 'fulfilled') {
            return settled.value;
        }

        const worker = request.workers[index];
        const failureResult: TaskResult = {
            workerId: worker.id,
            workerType: worker.type,
            label: worker.label,
            status: 'failure',
            output: '',
            durationMs: 0,
            error: settled.reason instanceof Error ? settled.reason.message : String(settled.reason),
        };

        graph.markCompleted(worker.id, failureResult);
        eventBus.emit({
            type: 'task-blocked',
            timestamp: new Date().toISOString(),
            source: 'coordinator',
            severity: 'warning',
            title: `Coordinator worker failed: ${worker.label}`,
            detail: failureResult.error ?? 'Worker failed',
            stage: 'coordinate',
            agent: worker.label,
            reason: failureResult.error ?? 'Worker failed',
        });

        return failureResult;
    });

    const synthesizedOutput = synthesizeResults(request.goal, workerResults);
    const findings = synthesizeFindings(workerResults);
    const synthesis: CoordinatorSynthesisResult = {
        format: 'markdown-v1',
        content: synthesizedOutput,
        findings,
    };
    const totalDurationMs = Date.now() - startTime;
    const summary = graph.getSummary();

    eventBus.emit({
        type: 'task-completed',
        timestamp: new Date().toISOString(),
        source: 'coordinator',
        severity: 'success',
        title: 'Coordinator run complete',
        detail: `${summary.completed} completed, ${summary.failed} failed`,
        stage: 'coordinate',
        agent: 'Coordinator',
        summary: `Coordination complete — ${summary.completed} completed, ${summary.failed} failed`,
    });

    return {
        title: request.title,
        goal: request.goal,
        workerResults,
        synthesis,
        synthesizedOutput,
        totalDurationMs,
        summary,
    };
}
