import * as fs from 'fs';
import * as path from 'path';
import type { JunaiEvent, JunaiEventBus } from '../background/events';
import type {
    DreamCoordinatorRun,
    DreamMemorySummary,
    MemoryConsolidationResult,
    MemoryConflict,
    MemoryFactRecord,
    MemorySignalKind,
} from './types';

const DREAM_MEMORY_RELATIVE_PATH = path.join('.github', 'dream-memory.json');
const DREAM_SCHEMA_VERSION = 'dream-memory-v1';
const MAX_FACTS = 200;
const SINGLE_HIT_PRUNE_DAYS = 14;
const MIN_RUN_INTERVAL_MS = 30_000;
const DEBOUNCE_MS = 10_000;
const MAX_REPO_FACT_SIGNALS_PER_RUN = 10;

interface MemorySignal {
    kind: MemorySignalKind;
    key: string;
    summary: string;
    detail?: string;
    source: string;
    observedAt: string;
}

interface DreamMemoryState {
    version: string;
    updatedAt: string;
    runs: number;
    facts: MemoryFactRecord[];
    dedupeIndex: Record<string, string>;
}

export interface DreamMemoryEngineOptions {
    workspaceRoot: string;
    eventBus: JunaiEventBus;
    onLog?: (message: string) => void;
}

function nowIso(): string {
    return new Date().toISOString();
}

function normalizeText(value: string): string {
    return value.trim().toLowerCase().replace(/\s+/g, ' ');
}

function makeFingerprint(signal: MemorySignal): string {
    return `${signal.kind}:${normalizeText(signal.key || signal.summary)}`;
}

function createEmptyState(): DreamMemoryState {
    return {
        version: DREAM_SCHEMA_VERSION,
        updatedAt: nowIso(),
        runs: 0,
        facts: [],
        dedupeIndex: {},
    };
}

function slugify(value: string): string {
    const slug = normalizeText(value)
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');
    return slug || 'fact';
}

function createFactId(signal: MemorySignal): string {
    const rand = Math.random().toString(36).slice(2, 8);
    return `${signal.kind}-${Date.now()}-${slugify(signal.key).slice(0, 40)}-${rand}`;
}

function readState(filePath: string): DreamMemoryState {
    if (!fs.existsSync(filePath)) {
        return createEmptyState();
    }

    try {
        const parsed = JSON.parse(fs.readFileSync(filePath, 'utf8')) as Partial<DreamMemoryState>;
        const state: DreamMemoryState = {
            version: parsed.version ?? DREAM_SCHEMA_VERSION,
            updatedAt: parsed.updatedAt ?? nowIso(),
            runs: typeof parsed.runs === 'number' ? parsed.runs : 0,
            facts: Array.isArray(parsed.facts) ? parsed.facts : [],
            dedupeIndex: parsed.dedupeIndex ?? {},
        };

        const factsById = new Map(state.facts.map((fact) => [fact.id, fact]));
        for (const [fingerprint, factId] of Object.entries(state.dedupeIndex)) {
            if (!factsById.has(factId)) {
                delete state.dedupeIndex[fingerprint];
            }
        }
        for (const fact of state.facts) {
            const fingerprint = `${fact.kind}:${normalizeText(fact.key)}`;
            if (!state.dedupeIndex[fingerprint]) {
                state.dedupeIndex[fingerprint] = fact.id;
            }
        }

        return state;
    } catch {
        return createEmptyState();
    }
}

function writeState(filePath: string, state: DreamMemoryState): void {
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, JSON.stringify(state, null, 2), 'utf8');
}

function dedupeSignals(signals: readonly MemorySignal[]): MemorySignal[] {
    const seen = new Set<string>();
    const unique: MemorySignal[] = [];

    for (const signal of signals) {
        const fingerprint = makeFingerprint(signal);
        if (seen.has(fingerprint)) {
            continue;
        }
        seen.add(fingerprint);
        unique.push(signal);
    }

    return unique;
}

function pruneFacts(state: DreamMemoryState): MemoryFactRecord[] {
    const pruned: MemoryFactRecord[] = [];
    const pruneBeforeMs = Date.now() - SINGLE_HIT_PRUNE_DAYS * 24 * 60 * 60 * 1000;

    const staleSingleHitIds = new Set(
        state.facts
            .filter((fact) => fact.hitCount <= 1 && Date.parse(fact.lastSeenAt) < pruneBeforeMs)
            .map((fact) => fact.id),
    );

    const factsByRecency = [...state.facts].sort((a, b) => Date.parse(a.lastSeenAt) - Date.parse(b.lastSeenAt));
    const overflowIds = new Set<string>();
    const retainedCount = state.facts.length - staleSingleHitIds.size;
    if (retainedCount > MAX_FACTS) {
        const toRemove = retainedCount - MAX_FACTS;
        for (const fact of factsByRecency) {
            if (staleSingleHitIds.has(fact.id)) {
                continue;
            }
            overflowIds.add(fact.id);
            if (overflowIds.size >= toRemove) {
                break;
            }
        }
    }

    const allPruneIds = new Set([...staleSingleHitIds, ...overflowIds]);
    if (allPruneIds.size === 0) {
        return pruned;
    }

    state.facts = state.facts.filter((fact) => {
        if (!allPruneIds.has(fact.id)) {
            return true;
        }
        pruned.push(fact);
        return false;
    });

    for (const [fingerprint, factId] of Object.entries(state.dedupeIndex)) {
        if (allPruneIds.has(factId)) {
            delete state.dedupeIndex[fingerprint];
        }
    }

    return pruned;
}

function sanitizeLine(line: string): string {
    return line
        .replace(/`/g, '')
        .replace(/^[-*]\s*/, '')
        .trim();
}

function extractRepoFactSignals(worker: DreamCoordinatorRun['workerResults'][number], observedAt: string): MemorySignal[] {
    const lines = worker.output.split('\n').map((line) => line.trim()).filter(Boolean);
    const candidateLines = lines.filter((line) =>
        line.startsWith('- `')
        && (line.includes('✅ exists') || line.includes('Exports:') || line.includes('TODOs/FIXMEs:') || line.includes('Test patterns:')),
    );

    return candidateLines.slice(0, MAX_REPO_FACT_SIGNALS_PER_RUN).map((line) => {
        const summary = sanitizeLine(line);
        return {
            kind: 'repo-fact',
            key: `${worker.workerId}:${summary}`,
            summary: `Repo fact: ${summary}`,
            detail: line,
            source: 'coordinator',
            observedAt,
        };
    });
}

function mapEventToSignal(event: JunaiEvent): MemorySignal | null {
    const observedAt = event.timestamp || nowIso();

    switch (event.type) {
        case 'task-completed':
            return {
                kind: 'workflow-success',
                key: `${event.source}:${event.stage}:${event.agent}:${event.summary}`,
                summary: `${event.source} completed ${event.stage} (${event.agent}) — ${event.summary}`,
                source: event.source,
                observedAt,
            };

        case 'task-blocked':
            return {
                kind: 'failure-mode',
                key: `${event.source}:${event.stage}:${event.agent}:${event.reason}`,
                summary: `${event.source} blocked ${event.stage} (${event.agent}) — ${event.reason}`,
                source: event.source,
                observedAt,
            };

        case 'approval-needed':
            return {
                kind: 'rejected-approach',
                key: `${event.source}:${event.stage}:${event.action}:${event.riskTier}`,
                summary: `Approval required for ${event.action} (${event.riskTier}) at ${event.stage}`,
                detail: `Agent: ${event.agent}`,
                source: event.source,
                observedAt,
            };

        case 'background-result':
            return {
                kind: event.status === 'success' ? 'workflow-success' : 'failure-mode',
                key: `${event.source}:${event.taskId}:${event.status}`,
                summary: `Background task ${event.taskId} ${event.status} — ${event.summary}`,
                source: event.source,
                observedAt,
            };

        case 'memory-consolidated':
            return null;

        default:
            return null;
    }
}

export class DreamMemoryEngine {
    private readonly memoryFilePath: string;
    private readonly pendingSignals = new Map<string, MemorySignal>();
    private flushTimer: ReturnType<typeof setTimeout> | undefined;
    private lastRunAtMs = 0;
    private unsubscribe: (() => void) | null = null;

    constructor(
        private readonly options: DreamMemoryEngineOptions,
    ) {
        this.memoryFilePath = path.join(options.workspaceRoot, DREAM_MEMORY_RELATIVE_PATH);
        this.unsubscribe = options.eventBus.onAny((event) => this.onEvent(event));
    }

    recordCoordinatorRun(run: DreamCoordinatorRun): MemoryConsolidationResult | null {
        const observedAt = nowIso();
        const signals: MemorySignal[] = [];

        if (run.summary.failed === 0) {
            signals.push({
                kind: 'workflow-success',
                key: `coordinator-run:${run.goal}:${run.summary.total}`,
                summary: `Coordinator run succeeded for goal "${run.goal}" (${run.summary.completed}/${run.summary.total} workers)`,
                source: 'coordinator',
                observedAt,
            });
        } else {
            signals.push({
                kind: 'failure-mode',
                key: `coordinator-run:${run.goal}:failed=${run.summary.failed}`,
                summary: `Coordinator run had failures for goal "${run.goal}" (${run.summary.failed} failed workers)`,
                source: 'coordinator',
                observedAt,
            });
        }

        for (const worker of run.workerResults) {
            if (worker.status === 'success') {
                signals.push(...extractRepoFactSignals(worker, observedAt));
                continue;
            }

            signals.push({
                kind: 'failure-mode',
                key: `worker-failure:${worker.workerId}:${worker.error ?? 'unknown'}`,
                summary: `Worker ${worker.workerId} failed — ${worker.error ?? 'Unknown error'}`,
                source: 'coordinator',
                observedAt,
            });
        }

        if (signals.length === 0) {
            return null;
        }

        return this.applyConsolidation(signals, 'coordinator-run');
    }

    private onEvent(event: JunaiEvent): void {
        const signal = mapEventToSignal(event);
        if (!signal) {
            return;
        }

        this.pendingSignals.set(makeFingerprint(signal), signal);

        const shouldFlushImmediately =
            event.type === 'task-blocked'
            || (event.type === 'background-result' && event.status === 'failure')
            || this.pendingSignals.size >= 4;

        if (shouldFlushImmediately) {
            this.flushPending('significant-event');
            return;
        }

        this.scheduleFlush();
    }

    private scheduleFlush(): void {
        if (this.flushTimer) {
            return;
        }

        this.flushTimer = setTimeout(() => {
            this.flushTimer = undefined;
            this.flushPending('debounced-event');
        }, DEBOUNCE_MS);
    }

    private flushPending(reason: 'significant-event' | 'debounced-event' | 'dispose'): MemoryConsolidationResult | null {
        if (this.pendingSignals.size === 0) {
            return null;
        }

        if (reason !== 'dispose' && (Date.now() - this.lastRunAtMs) < MIN_RUN_INTERVAL_MS) {
            this.scheduleFlush();
            return null;
        }

        const signals = Array.from(this.pendingSignals.values());
        this.pendingSignals.clear();
        return this.applyConsolidation(signals, reason);
    }

    private applyConsolidation(
        signals: readonly MemorySignal[],
        reason: 'coordinator-run' | 'significant-event' | 'debounced-event' | 'dispose',
    ): MemoryConsolidationResult {
        const uniqueSignals = dedupeSignals(signals);
        const state = readState(this.memoryFilePath);
        const result: MemoryConsolidationResult = {
            factsAdded: [],
            factsUpdated: [],
            factsPruned: [],
            conflicts: [],
        };

        for (const signal of uniqueSignals) {
            const fingerprint = makeFingerprint(signal);
            const existingId = state.dedupeIndex[fingerprint];
            const existing = existingId
                ? state.facts.find((fact) => fact.id === existingId)
                : undefined;

            if (existing) {
                if (normalizeText(existing.summary) !== normalizeText(signal.summary)) {
                    const conflict: MemoryConflict = {
                        key: signal.key,
                        existingFactId: existing.id,
                        existingSummary: existing.summary,
                        incomingSummary: signal.summary,
                        reason: 'conflicting-summary',
                    };
                    result.conflicts.push(conflict);

                    if (signal.summary.length > existing.summary.length) {
                        existing.summary = signal.summary;
                    }
                }

                existing.lastSeenAt = signal.observedAt;
                existing.hitCount += 1;
                if (signal.detail && (!existing.detail || signal.detail.length > existing.detail.length)) {
                    existing.detail = signal.detail;
                }
                if (!existing.sources.includes(signal.source)) {
                    existing.sources.push(signal.source);
                }
                result.factsUpdated.push({ ...existing, sources: [...existing.sources] });
                continue;
            }

            const fact: MemoryFactRecord = {
                id: createFactId(signal),
                kind: signal.kind,
                key: signal.key,
                summary: signal.summary,
                detail: signal.detail,
                sources: [signal.source],
                firstSeenAt: signal.observedAt,
                lastSeenAt: signal.observedAt,
                hitCount: 1,
            };
            state.facts.push(fact);
            state.dedupeIndex[fingerprint] = fact.id;
            result.factsAdded.push({ ...fact, sources: [...fact.sources] });
        }

        result.factsPruned = pruneFacts(state);
        state.updatedAt = nowIso();
        state.runs += 1;
        state.facts.sort((a, b) => Date.parse(b.lastSeenAt) - Date.parse(a.lastSeenAt));

        writeState(this.memoryFilePath, state);
        this.lastRunAtMs = Date.now();

        const promotedCount = result.factsAdded.length + result.factsUpdated.length;
        if (promotedCount > 0 || result.factsPruned.length > 0 || result.conflicts.length > 0) {
            this.options.eventBus.emit({
                type: 'memory-consolidated',
                timestamp: nowIso(),
                source: 'dream',
                severity: 'info',
                title: 'Dream memory consolidated',
                detail: `+${promotedCount} promoted, ${result.factsPruned.length} pruned, ${result.conflicts.length} conflicts`,
                itemsPruned: result.factsPruned.length,
                itemsPromoted: promotedCount,
            });
        }

        if (this.options.onLog && (promotedCount > 0 || result.factsPruned.length > 0)) {
            this.options.onLog(
                `[dream] ${reason}: +${result.factsAdded.length} added, ${result.factsUpdated.length} updated, ${result.factsPruned.length} pruned, ${result.conflicts.length} conflicts`,
            );
        }

        return result;
    }

    dispose(): void {
        if (this.flushTimer) {
            clearTimeout(this.flushTimer);
            this.flushTimer = undefined;
        }

        this.flushPending('dispose');

        if (this.unsubscribe) {
            this.unsubscribe();
            this.unsubscribe = null;
        }
    }
}

export function createDreamMemoryEngine(options: DreamMemoryEngineOptions): DreamMemoryEngine {
    return new DreamMemoryEngine(options);
}

export function readDreamMemorySummary(workspaceRoot: string): DreamMemorySummary | null {
    const filePath = path.join(workspaceRoot, DREAM_MEMORY_RELATIVE_PATH);
    if (!fs.existsSync(filePath)) {
        return null;
    }

    try {
        const state = JSON.parse(fs.readFileSync(filePath, 'utf8')) as Partial<DreamMemoryState>;
        const facts = Array.isArray(state.facts) ? state.facts : [];
        return {
            factCount: facts.length,
            runs: typeof state.runs === 'number' ? state.runs : 0,
            lastUpdatedAt: typeof state.updatedAt === 'string' ? state.updatedAt : nowIso(),
        };
    } catch {
        return null;
    }
}
