export type FeatureFlag = 'coordinator' | 'dream' | 'deepPlan' | 'proactive';

export interface ExperimentalFeatureDefinition {
    flag: FeatureFlag;
    implemented: boolean;
    commandId?: string;
    statusLabel: string;
    comingSoon?: string;
}

const EXPERIMENTAL_FEATURE_MANIFEST: readonly ExperimentalFeatureDefinition[] = [
    {
        flag: 'coordinator',
        implemented: true,
        commandId: 'junai.coordinate',
        statusLabel: 'Coordinator Mode',
    },
    {
        flag: 'dream',
        implemented: true,
        statusLabel: 'Dream Memory Consolidation',
    },
    {
        flag: 'deepPlan',
        implemented: true,
        commandId: 'junai.deepPlan',
        statusLabel: 'Deep Plan Mode',
    },
    {
        flag: 'proactive',
        implemented: true,
        statusLabel: 'KAIROS-lite Proactive Assistant',
    },
];

export type ExperimentalFeatureStatus = ExperimentalFeatureDefinition & { enabled: boolean };

export function getExperimentalFeatureManifest(): readonly ExperimentalFeatureDefinition[] {
    return EXPERIMENTAL_FEATURE_MANIFEST;
}

export function getExperimentalFeatureStatus(
    flags: Record<FeatureFlag, boolean>,
): ExperimentalFeatureStatus[] {
    return EXPERIMENTAL_FEATURE_MANIFEST.map((feature) => ({
        ...feature,
        enabled: flags[feature.flag],
    }));
}
