import type { EventSeverity, JunaiEvent } from './events';

const DEFAULT_DEDUPE_WINDOW_MS = 120_000;
const DEFAULT_POPUP_COOLDOWN_MS = 15_000;
const DEFAULT_STATUS_DURATION_MS = 6_000;
const DEFAULT_STATUS_COOLDOWN_MS = 2_500;

export type ProactiveNoticeKind =
    | 'background-result'
    | 'deep-plan-ready'
    | 'deep-plan-approved'
    | 'blocked'
    | 'approval-needed'
    | 'dream-memory-consolidated'
    | 'coordinator-complete';

export type ProactiveSurface = 'popup' | 'status' | 'log';

export interface ProactiveNotice {
    id: string;
    kind: ProactiveNoticeKind;
    title: string;
    detail?: string;
    severity: EventSeverity;
    dedupeKey?: string;
    surface: ProactiveSurface;
    createdAt: string;
}

export interface ProactivePolicyOptions {
    dedupeWindowMs: number;
    popupCooldownMs: number;
    statusDurationMs: number;
    statusCooldownMs: number;
}

export interface ProactivePolicyState {
    dedupeSeenAt: Map<string, number>;
    lastPopupAtMs: number;
    lastStatusAtMs: number;
}

export interface ProactiveDecision {
    notice: ProactiveNotice | null;
    surface: ProactiveSurface | null;
    suppressedReason?: 'filtered' | 'deduped';
    downgradedFromPopup?: boolean;
    downgradedFromStatus?: boolean;
}

const CRITICAL_NOTICE_KINDS: ReadonlySet<ProactiveNoticeKind> = new Set([
    'blocked',
    'approval-needed',
]);

function buildNoticeFromEvent(event: JunaiEvent): ProactiveNotice | null {
    switch (event.type) {
        case 'background-result': {
            const success = event.status === 'success';
            return {
                id: `background-${event.taskId}-${event.status}-${event.timestamp}`,
                kind: 'background-result',
                title: success ? 'Background step done' : 'Background step failed',
                detail: event.detail || event.summary,
                severity: success ? 'success' : 'warning',
                dedupeKey: `background:${event.taskId}:${event.status}:${event.summary}`,
                surface: success ? 'status' : 'popup',
                createdAt: event.timestamp,
            };
        }

        case 'approval-needed': {
            if (event.source === 'deep-plan' && event.stage === 'plan') {
                return {
                    id: `deep-plan-ready-${event.timestamp}`,
                    kind: 'deep-plan-ready',
                    title: 'Next step ready',
                    detail: event.detail || 'Review the plan and choose what to do next.',
                    severity: 'info',
                    dedupeKey: `deep-plan-ready:${event.source}:${event.stage}:${event.action}`,
                    surface: 'popup',
                    createdAt: event.timestamp,
                };
            }

            return {
                id: `approval-needed-${event.source}-${event.stage}-${event.timestamp}`,
                kind: 'approval-needed',
                title: event.title,
                detail: event.detail || `${event.agent} requested approval for ${event.action}.`,
                severity: event.riskTier === 'high' ? 'warning' : 'info',
                dedupeKey: `approval-needed:${event.source}:${event.stage}:${event.action}:${event.riskTier}`,
                surface: event.riskTier === 'high' ? 'popup' : 'status',
                createdAt: event.timestamp,
            };
        }

        case 'task-blocked': {
            return {
                id: `task-blocked-${event.source}-${event.stage}-${event.timestamp}`,
                kind: 'blocked',
                title: event.title,
                detail: event.detail || event.reason,
                severity: 'warning',
                dedupeKey: `task-blocked:${event.source}:${event.stage}:${event.reason}`,
                surface: 'popup',
                createdAt: event.timestamp,
            };
        }

        case 'task-completed': {
            if (event.source === 'deep-plan' && event.stage === 'plan-approved') {
                return {
                    id: `deep-plan-approved-${event.timestamp}`,
                    kind: 'deep-plan-approved',
                    title: 'Plan approved',
                    detail: event.detail || event.summary,
                    severity: 'success',
                    dedupeKey: `deep-plan-approved:${event.source}:${event.stage}:${event.summary}`,
                    surface: 'status',
                    createdAt: event.timestamp,
                };
            }

            if (event.source === 'coordinator' && event.agent === 'Coordinator' && event.stage === 'coordinate') {
                return {
                    id: `coordinator-complete-${event.timestamp}`,
                    kind: 'coordinator-complete',
                    title: 'Coordinator review complete',
                    detail: event.detail || event.summary,
                    severity: 'success',
                    dedupeKey: `coordinator-complete:${event.summary}`,
                    surface: 'status',
                    createdAt: event.timestamp,
                };
            }

            return null;
        }

        case 'memory-consolidated': {
            return {
                id: `dream-memory-consolidated-${event.timestamp}`,
                kind: 'dream-memory-consolidated',
                title: 'Memory updated',
                detail: event.detail || `+${event.itemsPromoted} promoted, ${event.itemsPruned} pruned.`,
                severity: 'info',
                dedupeKey: `dream-memory:${event.itemsPromoted}:${event.itemsPruned}`,
                surface: 'log',
                createdAt: event.timestamp,
            };
        }

        default:
            return null;
    }
}

function resolvePolicyOptions(options?: Partial<ProactivePolicyOptions>): ProactivePolicyOptions {
    return {
        dedupeWindowMs: options?.dedupeWindowMs ?? DEFAULT_DEDUPE_WINDOW_MS,
        popupCooldownMs: options?.popupCooldownMs ?? DEFAULT_POPUP_COOLDOWN_MS,
        statusDurationMs: options?.statusDurationMs ?? DEFAULT_STATUS_DURATION_MS,
        statusCooldownMs: options?.statusCooldownMs ?? DEFAULT_STATUS_COOLDOWN_MS,
    };
}

function pruneDedupeCache(state: ProactivePolicyState, dedupeWindowMs: number, nowMs: number): void {
    for (const [key, seenAt] of state.dedupeSeenAt.entries()) {
        if ((nowMs - seenAt) > dedupeWindowMs) {
            state.dedupeSeenAt.delete(key);
        }
    }
}

export function createProactivePolicyState(): ProactivePolicyState {
    return {
        dedupeSeenAt: new Map<string, number>(),
        lastPopupAtMs: 0,
        lastStatusAtMs: 0,
    };
}

export function evaluateProactiveEvent(
    event: JunaiEvent,
    policyState: ProactivePolicyState,
    options?: Partial<ProactivePolicyOptions>,
    nowMs: number = Date.now(),
): ProactiveDecision {
    const resolvedOptions = resolvePolicyOptions(options);
    const notice = buildNoticeFromEvent(event);

    if (!notice) {
        return {
            notice: null,
            surface: null,
            suppressedReason: 'filtered',
        };
    }

    pruneDedupeCache(policyState, resolvedOptions.dedupeWindowMs, nowMs);

    if (notice.dedupeKey) {
        const previousSeenAt = policyState.dedupeSeenAt.get(notice.dedupeKey);
        if (typeof previousSeenAt === 'number' && (nowMs - previousSeenAt) <= resolvedOptions.dedupeWindowMs) {
            return {
                notice,
                surface: null,
                suppressedReason: 'deduped',
            };
        }
    }

    let surface: ProactiveSurface = notice.surface;
    let downgradedFromPopup = false;
    let downgradedFromStatus = false;

    if (
        surface === 'popup' &&
        (nowMs - policyState.lastPopupAtMs) <= resolvedOptions.popupCooldownMs &&
        !CRITICAL_NOTICE_KINDS.has(notice.kind)
    ) {
        surface = 'status';
        downgradedFromPopup = true;
    }

    if (
        surface === 'status' &&
        (notice.severity === 'info' || notice.severity === 'success') &&
        (nowMs - policyState.lastStatusAtMs) <= resolvedOptions.statusCooldownMs
    ) {
        surface = 'log';
        downgradedFromStatus = true;
    }

    if (notice.dedupeKey) {
        policyState.dedupeSeenAt.set(notice.dedupeKey, nowMs);
    }

    if (surface === 'popup') {
        policyState.lastPopupAtMs = nowMs;
    }
    if (surface === 'status') {
        policyState.lastStatusAtMs = nowMs;
    }

    return {
        notice,
        surface,
        downgradedFromPopup,
        downgradedFromStatus,
    };
}
