import type { JunaiEventBus } from './events';

export interface BackgroundTaskSpec<TResult> {
    taskId: string;
    source: string;
    run: () => Promise<TResult>;
    summarizeSuccess?: (result: TResult) => string;
    summarizeFailure?: (error: unknown) => string;
}

export interface BackgroundTaskOutcome<TResult> {
    status: 'success' | 'failure';
    result?: TResult;
    error?: string;
}

export async function runBackgroundTask<TResult>(
    eventBus: JunaiEventBus,
    task: BackgroundTaskSpec<TResult>,
): Promise<BackgroundTaskOutcome<TResult>> {
    try {
        const result = await task.run();
        const summary = task.summarizeSuccess?.(result) ?? 'Background task completed successfully';
        eventBus.emit({
            type: 'background-result',
            timestamp: new Date().toISOString(),
            source: task.source,
            severity: 'success',
            title: 'Background step done',
            detail: summary,
            taskId: task.taskId,
            status: 'success',
            summary,
        });
        return {
            status: 'success',
            result,
        };
    } catch (error: unknown) {
        const message = task.summarizeFailure?.(error)
            ?? (error instanceof Error ? error.message : String(error));
        eventBus.emit({
            type: 'background-result',
            timestamp: new Date().toISOString(),
            source: task.source,
            severity: 'warning',
            title: 'Background step failed',
            detail: message,
            taskId: task.taskId,
            status: 'failure',
            summary: message,
        });
        return {
            status: 'failure',
            error: message,
        };
    }
}
