import {
    ACTION_CLASSIFICATIONS,
    PROTECTED_ACTIONS,
    type ActionClassification,
    type ActionName,
    type ProtectedAction,
    type RiskTier,
} from './riskTiers';
import { DEFAULT_PROTECTED_PATH_PATTERNS, isProtectedPath } from './protectedPaths';

const classificationMap = new Map<ActionName, ActionClassification>(
    ACTION_CLASSIFICATIONS.map((classification) => [classification.action, classification]),
);

export interface PermissionResult {
    allowed: boolean;
    tier: RiskTier;
    reason: string;
    requiresApproval: boolean;
}

export function isProtectedAction(action: string): action is ProtectedAction {
    return PROTECTED_ACTIONS.has(action as ProtectedAction);
}

export function checkPermission(
    action: string,
    mode: string,
    filePath?: string,
    protectedPathPatterns: readonly string[] = DEFAULT_PROTECTED_PATH_PATTERNS,
): PermissionResult {
    const classification = classificationMap.get(action as ActionName);
    let tier: RiskTier = classification?.tier ?? 'medium';

    if (isProtectedAction(action)) {
        tier = 'high';
    }

    if (filePath && isProtectedPath(filePath, protectedPathPatterns)) {
        tier = 'high';
    }

    switch (mode) {
        case 'supervised':
            return {
                allowed: tier === 'low',
                tier,
                reason: tier === 'low'
                    ? 'Low-risk action — proceeding'
                    : `Supervised mode — ${tier}-risk action requires manual approval`,
                requiresApproval: tier !== 'low',
            };

        case 'assisted':
        case 'autopilot':
            return {
                allowed: tier !== 'high',
                tier,
                reason: tier === 'high'
                    ? `High-risk action requires explicit approval even in ${mode} mode`
                    : `${tier}-risk action — proceeding in ${mode} mode`,
                requiresApproval: tier === 'high',
            };

        default:
            return {
                allowed: tier === 'low',
                tier,
                reason: `Unknown mode "${mode}" — defaulting to supervised behaviour`,
                requiresApproval: tier !== 'low',
            };
    }
}

export function getActionClassification(action: string): ActionClassification | undefined {
    return classificationMap.get(action as ActionName);
}

export function getAllClassifications(): readonly ActionClassification[] {
    return ACTION_CLASSIFICATIONS;
}
