import * as fs from 'fs';
import * as path from 'path';
import type {
    BuildDeepPlanRequestInput,
    DeepPlanConfidence,
    DeepPlanPhase,
    DeepPlanRequest,
    DeepPlanResult,
} from './planContracts';
import type { WorkspaceScanResult } from './workspaceScan';

const DEEP_PLAN_OUTPUT_DIR = path.join('.github', 'plans');

function normalizeLine(line: string): string {
    return line.trim().replace(/\s+/g, ' ');
}

function parseDelimitedInput(value?: string): string[] {
    if (!value) {
        return [];
    }

    return value
        .split(/[\n,;]+/g)
        .map(normalizeLine)
        .filter(Boolean);
}

function createPhaseId(index: number): string {
    return `phase-${index + 1}`;
}

function inferSummary(request: DeepPlanRequest): string {
    const scopeHint = request.scope.length > 0
        ? `in scope: ${request.scope.slice(0, 4).join(', ')}`
        : 'scope to be validated in discovery';

    return `${request.taskSummary} — ${scopeHint}`;
}

function inferAssumptions(request: DeepPlanRequest): string[] {
    const assumptions: string[] = [];

    assumptions.push('Deep Plan is advisory-first; implementation starts only after explicit user approval.');

    if (request.scope.length === 0) {
        assumptions.push('Scope is currently broad; Phase 1 will lock the smallest viable delivery slice.');
    } else {
        assumptions.push(`Scope is limited to: ${request.scope.join(', ')}.`);
    }

    if (request.constraints.length > 0) {
        assumptions.push(`Constraints are treated as hard boundaries: ${request.constraints.join('; ')}.`);
    } else {
        assumptions.push('No explicit constraints provided; backward compatibility and minimal disruption are assumed.');
    }

    if (request.contextReferences && request.contextReferences.length > 0) {
        assumptions.push(`Context references available: ${request.contextReferences.join(', ')}.`);
    }

    return assumptions;
}

function inferRisks(request: DeepPlanRequest, scan?: WorkspaceScanResult): string[] {
    const risks: string[] = [];
    const loweredSummary = request.taskSummary.toLowerCase();

    if (request.scope.length === 0) {
        risks.push('Scope ambiguity may cause rework unless bounded early.');
    }

    if (request.constraints.length === 0) {
        risks.push('Missing explicit constraints can hide rollout or compatibility risks.');
    }

    if (!request.contextReferences || request.contextReferences.length === 0) {
        if (!scan) {
            risks.push('Limited context references may miss dependency hotspots.');
        }
    }

    if (/migrat|refactor|rewrite|replace/.test(loweredSummary)) {
        risks.push('Structural change risk: hidden coupling can expand implementation effort.');
    }

    if (/security|auth|permission|compliance|privacy/.test(loweredSummary)) {
        risks.push('Security-sensitive scope requires explicit validation gates before rollout.');
    }

    if (scan) {
        if (!scan.hasTests) {
            risks.push('No test infrastructure detected — changes cannot be regression-checked automatically.');
        }
        if (!scan.hasCI) {
            risks.push('No CI pipeline detected — validate build and test gates manually before merge.');
        }
    }

    if (risks.length === 0) {
        risks.push('Execution drift risk: validate scope and acceptance criteria before implementation.');
    }

    return risks;
}

function filterRelevantFacts(facts: string[], taskSummary: string, topN: number): string[] {
    if (facts.length === 0) { return []; }

    const taskWords = taskSummary
        .toLowerCase()
        .split(/\W+/)
        .filter((w) => w.length > 3);

    const scored = facts.map((fact) => {
        const factLower = fact.toLowerCase();
        const matches = taskWords.filter((w) => factLower.includes(w)).length;
        return { fact, matches };
    });

    scored.sort((a, b) => b.matches - a.matches);

    // Prefer facts with at least 1 keyword match; fall back to highest-scored if none match
    const relevant = scored.filter((s) => s.matches > 0).slice(0, topN);
    return relevant.length > 0
        ? relevant.map((s) => s.fact)
        : scored.slice(0, topN).map((s) => s.fact);
}

function inferPhases(request: DeepPlanRequest, scan?: WorkspaceScanResult): DeepPlanPhase[] {
    const scopeTasks = request.scope.length > 0
        ? request.scope.slice(0, 5).map((item) => `Validate and map impact for ${item}.`)
        : [
            'Identify top impacted modules/files and lock the minimal viable scope.',
            'Define explicit out-of-scope items to prevent plan expansion.',
        ];

    const constraintTasks = request.constraints.length > 0
        ? request.constraints.slice(0, 5).map((item) => `Encode constraint guardrail: ${item}.`)
        : ['Define baseline quality constraints (compatibility, testability, rollback safety).'];

    // Add workspace-aware scope tasks when scan data is available
    if (scan) {
        const techNames = scan.techStack.map((s) => s.name);
        if (techNames.length > 0) {
            scopeTasks.push(`Tech stack detected: ${techNames.slice(0, 6).join(', ')} — verify compatibility with planned changes.`);
        }
        if (scan.entryPoint) {
            scopeTasks.push(`Entry point: ${scan.entryPoint} — trace impact from this module.`);
        }
    }

    const summaryLower = request.taskSummary.toLowerCase();
    const phases: DeepPlanPhase[] = [
        {
            id: createPhaseId(0),
            title: 'Scope & Constraints Alignment',
            objective: inferPhase1Objective(summaryLower),
            tasks: [
                'Restate the problem in one sentence and define success criteria.',
                ...scopeTasks,
                ...constraintTasks,
                'Record open questions and explicit assumption ownership.',
            ],
        },
        {
            id: createPhaseId(1),
            title: 'Implementation Slicing',
            objective: 'Break work into low-risk phased slices with clear dependencies.',
            dependencies: [createPhaseId(0)],
            tasks: [
                'Define phase-by-phase deliverables with acceptance checks.',
                'Sequence work from safest foundation to higher-risk integration points.',
                'Specify rollback and fallback strategy for each risky slice.',
            ],
        },
    ];

    // Insert test phase when tests exist in the project
    if (scan?.hasTests) {
        phases[1].tasks.push(`Update existing test suite (detected at: ${scan.testPaths.join(', ')}).`);
    }

    phases.push({
        id: createPhaseId(2),
        title: 'Validation & Approval Gate',
        objective: 'Ensure plan quality and obtain explicit approval before implementation.',
        dependencies: [createPhaseId(1)],
        tasks: [
            scan?.hasTests
                ? `Run existing tests (${scan.testPaths.join(', ')}) and verify no regressions.`
                : 'Run compile/test/type-check expectations for each slice.',
            scan?.hasCI
                ? `Verify CI pipeline (${scan.ciPaths.join(', ')}) passes with planned changes.`
                : 'Confirm build and validation steps are defined.',
            'Confirm risks and open questions are explicitly tracked.',
            'Produce final approval summary with go/no-go recommendation.',
        ],
    });

    if (/deploy|release|rollout|launch|production/.test(summaryLower)) {
        phases.push({
            id: createPhaseId(3),
            title: 'Rollout & Post-Launch Follow-up',
            objective: 'Plan safe delivery sequencing and post-implementation learning loop.',
            dependencies: [createPhaseId(2)],
            tasks: [
                'Define staged rollout checkpoints and monitoring expectations.',
                'Define post-launch validation signals and fallback triggers.',
                'Capture lessons learned for memory consolidation and future planning reuse.',
            ],
        });
    }

    // Add dream memory insights to the last phase — filtered by relevance to the task
    if (scan && scan.dreamMemoryFacts.length > 0) {
        const lastPhase = phases[phases.length - 1];
        const relevantFacts = filterRelevantFacts(scan.dreamMemoryFacts, request.taskSummary, 3);
        if (relevantFacts.length > 0) {
            lastPhase.tasks.push(
                `Incorporate relevant dream memory insights: ${relevantFacts.join('; ')}.`,
            );
        }
    }

    return phases;
}

function inferConfidence(request: DeepPlanRequest, risks: string[], scan?: WorkspaceScanResult): DeepPlanConfidence {
    let score = 0;
    if (request.taskSummary.length >= 24) { score += 1; }
    if (request.scope.length > 0) { score += 1; }
    if (request.constraints.length > 0) { score += 1; }
    if ((request.contextReferences?.length ?? 0) > 0) { score += 1; }
    if (scan) { score += 1; } // workspace scan adds grounding
    if (scan?.hasTests) { score += 1; } // test coverage adds confidence
    if (risks.length >= 4) { score -= 1; }

    if (score >= 5) { return 'high'; }
    if (score >= 2) { return 'medium'; }
    return 'low';
}

function inferPhase1Objective(summaryLower: string): string {
    if (/expense|budget|financ|payment|receipt|spend/.test(summaryLower)) {
        return 'Confirm the expense data model and minimum required flows before any implementation begins.';
    }
    if (/\bnote|notebook|journal|wiki|knowledge base/.test(summaryLower)) {
        return 'Define the content model, search requirements, and desired UX before touching any code.';
    }
    if (/\btask|\btodo|ticket|backlog|kanban/.test(summaryLower)) {
        return 'Define the MVP feature set and lock the task lifecycle before any implementation begins.';
    }
    if (/migrat|refactor|rewrite|replace/.test(summaryLower)) {
        return 'Map the full impact surface and lock a safe, minimal change slice before writing any code.';
    }
    if (/\bapi\b|\bservice\b|integrat|endpoint|webhook/.test(summaryLower)) {
        return 'Confirm the integration contract and failure boundary before any implementation begins.';
    }
    return 'Turn the rough idea into a bounded, approval-ready implementation target.';
}

function inferTaskSpecificNextAction(request: DeepPlanRequest, _phases: DeepPlanPhase[]): string {
    const summary = request.taskSummary.toLowerCase();
    const scopeHint = request.scope.slice(0, 2).join(' and ');
    const constraintHint = request.constraints[0] ?? '';

    // Task-category detection — most specific patterns first
    if (/expense|budget|financ|payment|receipt|spend/.test(summary)) {
        const detail = constraintHint ? `, keeping "${constraintHint}" as a hard boundary` : '';
        return `Lock the minimum expense entry and summary flows${detail}, then confirm the data model.`;
    }

    if (/\bnote|notebook|journal|wiki|knowledge base/.test(summary)) {
        const detail = scopeHint ? ` in ${scopeHint}` : '';
        return `Define the note model, tag structure, and simplest workable search experience${detail}.`;
    }

    if (/\btask|\btodo|ticket|backlog|kanban/.test(summary)) {
        const detail = constraintHint ? ` within the "${constraintHint}" constraint` : '';
        return `Define the MVP task model, status states, and the minimum create-and-view flow${detail}.`;
    }

    if (/auth(?:entication|oriz)|login|sign[\s-]?in|permission|access control/.test(summary)) {
        return 'Confirm the authentication boundary, token strategy, and session lifecycle before writing any code.';
    }

    if (/migrat|refactor|rewrite|replace/.test(summary)) {
        const detail = scopeHint ? ` starting from ${scopeHint}` : '';
        return `Map the dependency footprint and identify hidden coupling${detail} before slicing the work.`;
    }

    if (/deploy|release|rollout|\bci\b|pipeline|launch/.test(summary)) {
        return 'Define the target environment, rollout checkpoints, and first health signal before any automation.';
    }

    if (/\bapi\b|endpoint|integrat|service|webhook/.test(summary)) {
        const detail = scopeHint ? ` for ${scopeHint}` : '';
        return `Confirm the API contract, error boundary, and retry expectations${detail} before implementation.`;
    }

    if (/\btest|\bspec\b|\bqa\b|quality|coverage/.test(summary)) {
        return 'Identify the highest-value coverage gaps and define the test boundary before writing any specs.';
    }

    if (/performance|latency|speed|optimiz|cache|scale/.test(summary)) {
        return 'Establish a measurable baseline and isolate the single highest-impact bottleneck before optimizing.';
    }

    // Generic fallback — concise, advisory-first
    const scopeSuffix = scopeHint ? ` scoped to ${scopeHint}` : '';
    const constraintSuffix = constraintHint ? `, with "${constraintHint}" as a hard boundary` : '';
    return `Define the success criteria and lock the smallest viable delivery slice${scopeSuffix}${constraintSuffix}.`;
}

export function buildDeepPlanRequest(input: BuildDeepPlanRequestInput): DeepPlanRequest {
    return {
        taskSummary: normalizeLine(input.taskSummary),
        scope: parseDelimitedInput(input.scopeInput),
        constraints: parseDelimitedInput(input.constraintsInput),
        contextReferences: (input.contextReferences ?? []).map(normalizeLine).filter(Boolean),
    };
}

export function createDeepPlanResult(request: DeepPlanRequest, scan?: WorkspaceScanResult): DeepPlanResult {
    const risks = inferRisks(request, scan);
    const summary = inferSummary(request);
    const assumptions = inferAssumptions(request);
    const phases = inferPhases(request, scan);
    const confidence = inferConfidence(request, risks, scan);
    const nextAction = inferTaskSpecificNextAction(request, phases);

    return {
        summary,
        assumptions,
        risks,
        phases,
        nextAction,
        confidence,
    };
}

export function renderDeepPlanMarkdown(request: DeepPlanRequest, result: DeepPlanResult, scan?: WorkspaceScanResult): string {
    const lines: string[] = [];

    lines.push('## Deep Plan Result');
    lines.push('');
    lines.push(`**Task Summary:** ${request.taskSummary}`);
    lines.push(`**Confidence:** ${result.confidence}`);
    if (scan) {
        lines.push(`**Workspace:** ${scan.packageName ?? scan.detectedLanguage} project`);
    }
    lines.push('');

    if (scan) {
        lines.push('### Workspace Context');
        lines.push(`- **Language:** ${scan.detectedLanguage}`);
        if (scan.techStack.length > 0) {
            const grouped = new Map<string, string[]>();
            for (const s of scan.techStack) {
                const list = grouped.get(s.category) ?? [];
                list.push(s.name);
                grouped.set(s.category, list);
            }
            for (const [category, names] of grouped) {
                lines.push(`- **${category}:** ${names.join(', ')}`);
            }
        }
        if (scan.hasTests) { lines.push(`- **Tests:** ${scan.testPaths.join(', ')}`); }
        if (scan.hasCI) { lines.push(`- **CI:** ${scan.ciPaths.join(', ')}`); }
        if (scan.dreamMemoryFacts.length > 0) {
            lines.push(`- **Dream memory:** ${scan.dreamMemoryFacts.length} facts available`);
        }
        lines.push('');
    }

    lines.push('### Summary');
    lines.push(result.summary);
    lines.push('');

    lines.push('### Scope');
    if (request.scope.length > 0) {
        for (const item of request.scope) {
            lines.push(`- ${item}`);
        }
    } else {
        lines.push('- Scope not explicitly provided (to be locked in Phase 1).');
    }
    lines.push('');

    lines.push('### Constraints');
    if (request.constraints.length > 0) {
        for (const item of request.constraints) {
            lines.push(`- ${item}`);
        }
    } else {
        lines.push('- No explicit constraints provided.');
    }
    lines.push('');

    lines.push('### Assumptions');
    for (const assumption of result.assumptions) {
        lines.push(`- ${assumption}`);
    }
    lines.push('');

    lines.push('### Risks & Open Questions');
    for (const risk of result.risks) {
        lines.push(`- ${risk}`);
    }
    lines.push('');

    lines.push('### Phased Implementation Outline');
    for (const phase of result.phases) {
        lines.push(`#### ${phase.id}: ${phase.title}`);
        lines.push(`Objective: ${phase.objective}`);
        if (phase.dependencies && phase.dependencies.length > 0) {
            lines.push(`Depends on: ${phase.dependencies.join(', ')}`);
        }
        for (const task of phase.tasks) {
            lines.push(`- ${task}`);
        }
        lines.push('');
    }

    lines.push('### Suggested Next Action');
    lines.push(result.nextAction);

    return lines.join('\n');
}

export function persistDeepPlanMarkdown(
    workspaceRoot: string,
    markdown: string,
): string {
    const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
    const outputDir = path.join(workspaceRoot, DEEP_PLAN_OUTPUT_DIR);
    fs.mkdirSync(outputDir, { recursive: true });
    const outputPath = path.join(outputDir, `deep-plan-${stamp}.md`);
    fs.writeFileSync(outputPath, markdown, 'utf8');
    return outputPath;
}
