import * as fs from 'fs';
import * as path from 'path';

export interface WorkspaceScanResult {
    techStack: TechStackSignal[];
    structure: DirectoryEntry[];
    hasTests: boolean;
    testPaths: string[];
    hasCI: boolean;
    ciPaths: string[];
    hasExistingPlans: boolean;
    planPaths: string[];
    dreamMemoryFacts: string[];
    entryPoint?: string;
    packageName?: string;
    detectedLanguage: 'typescript' | 'python' | 'unknown';
}

export interface TechStackSignal {
    name: string;
    source: string;
    category: 'runtime' | 'framework' | 'test' | 'build' | 'lint' | 'database' | 'other';
}

export interface DirectoryEntry {
    relativePath: string;
    type: 'file' | 'directory';
    depth: number;
}

const SKIP_DIRS = new Set(['.git', 'node_modules', '__pycache__', '.DS_Store', 'out', 'dist', '.venv', '.mypy_cache', '.pytest_cache', '.tox', 'coverage', '.next', 'build']);

const TEST_PATTERNS = [
    'tests/', 'test/', '__tests__/', 'spec/', '*.test.ts', '*.spec.ts',
    '*.test.js', '*.spec.js', 'test_*.py', '*_test.py', 'conftest.py',
    'jest.config', 'vitest.config', 'pytest.ini', 'setup.cfg',
];

const CI_PATTERNS = [
    '.github/workflows/', '.gitlab-ci.yml', 'Jenkinsfile',
    '.circleci/', 'azure-pipelines.yml', '.travis.yml',
];

function fileExists(workspaceRoot: string, relativePath: string): boolean {
    return fs.existsSync(path.resolve(workspaceRoot, relativePath));
}

function readFileQuiet(workspaceRoot: string, relativePath: string): string | null {
    const fullPath = path.resolve(workspaceRoot, relativePath);
    try {
        return fs.readFileSync(fullPath, 'utf8');
    } catch {
        return null;
    }
}

function listShallowDir(dirPath: string, workspaceRoot: string, maxDepth: number, currentDepth: number = 0): DirectoryEntry[] {
    if (currentDepth >= maxDepth) {
        return [];
    }

    const entries: DirectoryEntry[] = [];
    try {
        const dirEntries = fs.readdirSync(dirPath, { withFileTypes: true });
        for (const entry of dirEntries) {
            if (SKIP_DIRS.has(entry.name)) {
                continue;
            }
            const relativePath = path.relative(workspaceRoot, path.join(dirPath, entry.name));
            if (entry.isDirectory()) {
                entries.push({ relativePath, type: 'directory', depth: currentDepth });
                entries.push(...listShallowDir(path.join(dirPath, entry.name), workspaceRoot, maxDepth, currentDepth + 1));
            } else {
                entries.push({ relativePath, type: 'file', depth: currentDepth });
            }
        }
    } catch {
        // access denied or missing — skip silently
    }
    return entries;
}

function detectTechStack(workspaceRoot: string): { signals: TechStackSignal[]; language: 'typescript' | 'python' | 'unknown'; packageName?: string; entryPoint?: string } {
    const signals: TechStackSignal[] = [];
    let language: 'typescript' | 'python' | 'unknown' = 'unknown';
    let packageName: string | undefined;
    let entryPoint: string | undefined;

    // Check package.json
    const pkgJson = readFileQuiet(workspaceRoot, 'package.json');
    if (pkgJson) {
        language = 'typescript'; // default for JS/TS projects
        try {
            const pkg = JSON.parse(pkgJson);
            packageName = pkg.name;
            entryPoint = pkg.main;
            // For TypeScript/compiled projects, resolve back to the source entry point
            if (entryPoint && /^(dist|out|build)\//.test(entryPoint)) {
                const sourceCandidate = entryPoint
                    .replace(/^(dist|out|build)\//, 'src/')
                    .replace(/\.js$/, '.ts');
                if (fileExists(workspaceRoot, sourceCandidate)) {
                    entryPoint = sourceCandidate;
                }
            }

            const allDeps = { ...pkg.dependencies, ...pkg.devDependencies };
            const depCategories: Record<string, TechStackSignal['category']> = {
                'react': 'framework', 'vue': 'framework', 'angular': 'framework', 'svelte': 'framework',
                'next': 'framework', 'nuxt': 'framework', 'express': 'framework', 'fastify': 'framework',
                'jest': 'test', 'vitest': 'test', 'mocha': 'test', 'playwright': 'test', 'cypress': 'test',
                'typescript': 'build', 'webpack': 'build', 'vite': 'build', 'esbuild': 'build', 'rollup': 'build',
                'eslint': 'lint', 'prettier': 'lint', 'biome': 'lint',
                'prisma': 'database', 'typeorm': 'database', 'drizzle': 'database', 'sequelize': 'database',
            };

            for (const dep of Object.keys(allDeps ?? {})) {
                // Skip @types/* — they are type definitions, not runtime/framework deps
                if (dep.startsWith('@types/')) { continue; }
                const baseName = dep.replace(/^@[^/]+\//, '');
                for (const [keyword, category] of Object.entries(depCategories)) {
                    if (baseName.includes(keyword)) {
                        signals.push({ name: dep, source: 'package.json', category });
                    }
                }
            }

            if (allDeps?.['typescript'] || fileExists(workspaceRoot, 'tsconfig.json')) {
                language = 'typescript';
                // Only add if not already detected from the allDeps loop to avoid duplication
                if (!signals.some((s) => s.name === 'typescript')) {
                    signals.push({ name: 'typescript', source: 'tsconfig.json', category: 'build' });
                }
            }
        } catch {
            // malformed package.json — still detected as JS project
        }
    }

    // Check pyproject.toml / setup.py / requirements.txt
    const pyproject = readFileQuiet(workspaceRoot, 'pyproject.toml');
    if (pyproject) {
        language = 'python';
        const deps = pyproject.match(/^\s*"?([a-zA-Z0-9_-]+)"?\s*[>=<]/gm);
        const pyCategories: Record<string, TechStackSignal['category']> = {
            'fastapi': 'framework', 'django': 'framework', 'flask': 'framework', 'streamlit': 'framework',
            'fastmcp': 'framework', 'mcp': 'framework',
            'pytest': 'test', 'unittest': 'test', 'hypothesis': 'test',
            'sqlalchemy': 'database', 'alembic': 'database',
            'ruff': 'lint', 'mypy': 'lint', 'black': 'lint', 'flake8': 'lint',
        };
        for (const [keyword, category] of Object.entries(pyCategories)) {
            if (pyproject.toLowerCase().includes(keyword)) {
                signals.push({ name: keyword, source: 'pyproject.toml', category });
            }
        }
    } else if (fileExists(workspaceRoot, 'requirements.txt') || fileExists(workspaceRoot, 'setup.py')) {
        language = 'python';
    }

    return { signals, language, packageName, entryPoint };
}

function findMatchingPaths(workspaceRoot: string, patterns: string[]): string[] {
    const found: string[] = [];
    for (const pattern of patterns) {
        if (pattern.endsWith('/')) {
            // directory pattern
            const dirPath = path.resolve(workspaceRoot, pattern.slice(0, -1));
            if (fs.existsSync(dirPath) && fs.statSync(dirPath).isDirectory()) {
                found.push(pattern.slice(0, -1));
            }
        } else if (pattern.includes('*')) {
            // skip glob patterns for now — just check common filenames
            continue;
        } else {
            if (fileExists(workspaceRoot, pattern)) {
                found.push(pattern);
            }
        }
    }
    return found;
}

function loadDreamMemoryFacts(workspaceRoot: string): string[] {
    const content = readFileQuiet(workspaceRoot, path.join('.github', 'dream-memory.json'));
    if (!content) {
        return [];
    }
    try {
        const state = JSON.parse(content);
        const raw: Array<string | { summary?: string }> = state.facts ?? [];
        return raw
            .slice(0, 20)
            .map((f) => (typeof f === 'string' ? f : f.summary))
            .filter((s): s is string => typeof s === 'string' && s.length > 0);
    } catch {
        return [];
    }
}

export function scanWorkspace(workspaceRoot: string): WorkspaceScanResult {
    const { signals, language, packageName, entryPoint } = detectTechStack(workspaceRoot);
    const structure = listShallowDir(workspaceRoot, workspaceRoot, 2);
    const testPaths = findMatchingPaths(workspaceRoot, TEST_PATTERNS);
    const ciPaths = findMatchingPaths(workspaceRoot, CI_PATTERNS);
    const planPaths = findMatchingPaths(workspaceRoot, ['.github/plans/']);
    const dreamMemoryFacts = loadDreamMemoryFacts(workspaceRoot);

    return {
        techStack: signals,
        structure,
        hasTests: testPaths.length > 0,
        testPaths,
        hasCI: ciPaths.length > 0,
        ciPaths,
        hasExistingPlans: planPaths.length > 0,
        planPaths,
        dreamMemoryFacts,
        entryPoint,
        packageName,
        detectedLanguage: language,
    };
}

export function scanResultToContextLines(scan: WorkspaceScanResult): string[] {
    const lines: string[] = [];

    if (scan.packageName) {
        lines.push(`Project: ${scan.packageName}`);
    }
    lines.push(`Language: ${scan.detectedLanguage}`);

    if (scan.techStack.length > 0) {
        const frameworks = scan.techStack.filter((s) => s.category === 'framework').map((s) => s.name);
        const testLibs = scan.techStack.filter((s) => s.category === 'test').map((s) => s.name);
        const buildTools = scan.techStack.filter((s) => s.category === 'build').map((s) => s.name);
        const databases = scan.techStack.filter((s) => s.category === 'database').map((s) => s.name);

        if (frameworks.length > 0) { lines.push(`Frameworks: ${frameworks.join(', ')}`); }
        if (testLibs.length > 0) { lines.push(`Test libraries: ${testLibs.join(', ')}`); }
        if (buildTools.length > 0) { lines.push(`Build tools: ${buildTools.join(', ')}`); }
        if (databases.length > 0) { lines.push(`Database tools: ${databases.join(', ')}`); }
    }

    if (scan.hasTests) {
        lines.push(`Test directories: ${scan.testPaths.join(', ')}`);
    }
    if (scan.hasCI) {
        lines.push(`CI config: ${scan.ciPaths.join(', ')}`);
    }

    const topDirs = scan.structure
        .filter((e) => e.type === 'directory' && e.depth === 0)
        .map((e) => e.relativePath);
    if (topDirs.length > 0) {
        lines.push(`Top-level directories: ${topDirs.join(', ')}`);
    }

    const topFiles = scan.structure
        .filter((e) => e.type === 'file' && e.depth === 0)
        .map((e) => e.relativePath);
    if (topFiles.length > 0) {
        lines.push(`Root files: ${topFiles.join(', ')}`);
    }

    // Key source files — depth-1 files inside common source directories
    const srcFiles = scan.structure
        .filter((e) => e.type === 'file' && e.depth === 1)
        .map((e) => e.relativePath.replace(/\\/g, '/'));
    if (srcFiles.length > 0) {
        lines.push(`Key source files: ${srcFiles.join(', ')}`);
    }

    if (scan.dreamMemoryFacts.length > 0) {
        lines.push(`Dream memory (${scan.dreamMemoryFacts.length} facts): ${scan.dreamMemoryFacts.slice(0, 5).join('; ')}`);
    }

    return lines;
}
