export type WorkerType = 'explore' | 'verify' | 'review';

export interface WorkerSpec {
    id: string;
    type: WorkerType;
    label: string;
    prompt: string;
    scopePaths?: string[];
}

export type CoordinatorTaskSpec = WorkerSpec;

export type TaskStatus = 'pending' | 'running' | 'completed' | 'failed';

export interface TaskResult {
    workerId: string;
    workerType: WorkerType;
    label: string;
    status: 'success' | 'failure';
    output: string;
    durationMs: number;
    error?: string;
}

export interface TaskNode {
    worker: CoordinatorTaskSpec;
    status: TaskStatus;
    result?: TaskResult;
    startedAt?: string;
    completedAt?: string;
}

export class TaskGraph {
    private nodes: Map<string, TaskNode> = new Map();

    addWorker(worker: WorkerSpec): void {
        if (this.nodes.has(worker.id)) {
            throw new Error(`Worker ID "${worker.id}" already exists in task graph`);
        }
        this.nodes.set(worker.id, {
            worker,
            status: 'pending',
        });
    }

    getNode(workerId: string): TaskNode | undefined {
        return this.nodes.get(workerId);
    }

    getAllNodes(): TaskNode[] {
        return Array.from(this.nodes.values());
    }

    getPendingWorkers(): WorkerSpec[] {
        return this.getAllNodes()
            .filter((node) => node.status === 'pending')
            .map((node) => node.worker);
    }

    markRunning(workerId: string): void {
        const node = this.nodes.get(workerId);
        if (!node) {
            throw new Error(`Unknown worker: ${workerId}`);
        }
        node.status = 'running';
        node.startedAt = new Date().toISOString();
    }

    markCompleted(workerId: string, result: TaskResult): void {
        const node = this.nodes.get(workerId);
        if (!node) {
            throw new Error(`Unknown worker: ${workerId}`);
        }
        node.status = result.status === 'success' ? 'completed' : 'failed';
        node.result = result;
        node.completedAt = new Date().toISOString();
    }

    isComplete(): boolean {
        return this.getAllNodes().every((node) => node.status === 'completed' || node.status === 'failed');
    }

    getSummary(): { total: number; completed: number; failed: number; pending: number; running: number } {
        const nodes = this.getAllNodes();
        return {
            total: nodes.length,
            completed: nodes.filter((node) => node.status === 'completed').length,
            failed: nodes.filter((node) => node.status === 'failed').length,
            pending: nodes.filter((node) => node.status === 'pending').length,
            running: nodes.filter((node) => node.status === 'running').length,
        };
    }
}
